import { useState } from 'react';
import { Button, Drawer, Menu, MenuItem, Divider } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface AppNavMenuProps {
  onNavigate: (key: NavKey) => void;
}

const NAV_ITEMS: { key: NavKey; label: string }[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function AppNavMenu({ onNavigate }: AppNavMenuProps) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <Button onClick={() => setOpen(true)}>Меню</Button>

      <Drawer
        open={open}
        placement="left"
        title="Навигация"
        onClose={() => setOpen(false)}
      >
        <Menu aria-label="Основная навигация">
          {NAV_ITEMS.map((item) => (
            <MenuItem key={item.key} onSelect={() => select(item.key)}>
              {item.label}
            </MenuItem>
          ))}
          <Divider />
          <MenuItem tone="danger" onSelect={() => select('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </>
  );
}

